import{_ as a,o as n,c as t,a3 as o}from"./chunks/framework.Cc-oPviL.js";const u=JSON.parse('{"title":"05 · 内核态与系统调用：用户程序怎么\\"申请\\"做事","description":"","frontmatter":{},"headers":[],"relativePath":"bagu/os/05.md","filePath":"bagu/os/05.md"}'),e={name:"bagu/os/05.md"};function l(p,s,i,r,c,d){return n(),t("div",null,[...s[0]||(s[0]=[o(`<h1 id="_05-·-内核态与系统调用-用户程序怎么-申请-做事" tabindex="-1">05 · 内核态与系统调用：用户程序怎么&quot;申请&quot;做事 <a class="header-anchor" href="#_05-·-内核态与系统调用-用户程序怎么-申请-做事" aria-label="Permalink to &quot;05 · 内核态与系统调用：用户程序怎么&quot;申请&quot;做事&quot;">​</a></h1><blockquote><p>这篇篇幅最短，但它是前四篇的&quot;总闸门&quot;——进程、内存、锁、IO，用户程序想用任何一样，都必须从这里过。</p></blockquote><h2 id="一句话本质" tabindex="-1">一句话本质 <a class="header-anchor" href="#一句话本质" aria-label="Permalink to &quot;一句话本质&quot;">​</a></h2><p>硬件把 CPU 分成两个<strong>特权级</strong>：用户态只能算数，内核态才能碰硬件和别人的内存。系统调用就是那道<strong>唯一合法的门</strong>。</p><h2 id="生活类比-餐厅的前厅与后厨" tabindex="-1">生活类比：餐厅的前厅与后厨 <a class="header-anchor" href="#生活类比-餐厅的前厅与后厨" aria-label="Permalink to &quot;生活类比：餐厅的前厅与后厨&quot;">​</a></h2><ul><li><strong>用户态</strong>：前厅。客人能看菜单、能点菜、能聊天，但<strong>进不了后厨</strong>。</li><li><strong>内核态</strong>：后厨。能开火、能碰刀、能拿食材，也能碰所有客人的东西。</li><li><strong>系统调用</strong>：按铃叫服务员。<strong>这是唯一的通道</strong>，你不能自己推门进去。</li><li><strong>特权级检查</strong>：服务员会核对&quot;你点的这道菜后厨能不能做&quot;，不合法就退回（返回 <code>EPERM</code>）。</li><li><strong>中断</strong>：后厨的定时器响了，厨师必须停下手上活去处理（客人无法拒绝）。</li></ul><p>关键：<strong>后厨只有一个，前厅有很多桌</strong>。所以后厨必须极其可靠——它一崩，所有客人一起完。</p><h2 id="核心机制" tabindex="-1">核心机制 <a class="header-anchor" href="#核心机制" aria-label="Permalink to &quot;核心机制&quot;">​</a></h2><h3 id="一、特权级-为什么需要两态" tabindex="-1">一、特权级：为什么需要两态 <a class="header-anchor" href="#一、特权级-为什么需要两态" aria-label="Permalink to &quot;一、特权级：为什么需要两态&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>x86 有 4 个环（Ring 0 ~ Ring 3），实际只用两个：</span></span>
<span class="line"><span>  Ring 3  用户态：不能执行特权指令（改页表、关中断、直接读写端口）</span></span>
<span class="line"><span>  Ring 0  内核态：全部权限</span></span>
<span class="line"><span></span></span>
<span class="line"><span>一条指令能不能执行，由 CPU 硬件判断当前特权级，不是软件判断</span></span>
<span class="line"><span>&gt; 所以用户程序&quot;想&quot;绕过也没用，硬件直接给你一个 #GP 异常</span></span></code></pre></div><p><strong>哪些指令是特权的</strong>：修改 CR3（页表基址）、关中断（<code>cli</code>）、读写 IO 端口（<code>in</code>/<code>out</code>）、加载 IDT（中断向量表）、halt CPU。这些恰好都是&quot;能破坏整个系统&quot;的操作。</p><h3 id="二、一次系统调用的完整过程" tabindex="-1">二、一次系统调用的完整过程 <a class="header-anchor" href="#二、一次系统调用的完整过程" aria-label="Permalink to &quot;二、一次系统调用的完整过程&quot;">​</a></h3><p>以 <code>read(fd, buf, 100)</code> 为例：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用户态</span></span>
<span class="line"><span>  |</span></span>
<span class="line"><span>  ① 把系统调用号（read 是 0）放进寄存器 eax/rax</span></span>
<span class="line"><span>  |  参数放进 ebx/ecx/edx（或 rdi/rsi/rdx）</span></span>
<span class="line"><span>  |</span></span>
<span class="line"><span>  ② 执行 syscall 指令（或 int 0x80）</span></span>
<span class="line"><span>  |  &lt; 这一条指令让 CPU 硬件完成：切换特权级、跳到内核预设的入口</span></span>
<span class="line"><span>  v</span></span>
<span class="line"><span>内核态</span></span>
<span class="line"><span>  |</span></span>
<span class="line"><span>  ③ 硬件自动保存：返回地址、标志寄存器、栈指针 &gt; 切到内核栈</span></span>
<span class="line"><span>  |  （注意：不是保存&quot;所有寄存器&quot;，是按需保存，这是优化的关键）</span></span>
<span class="line"><span>  |</span></span>
<span class="line"><span>  ④ 查系统调用表 sys_call_table[0] &gt; 找到 sys_read</span></span>
<span class="line"><span>  |</span></span>
<span class="line"><span>  ⑤ 检查参数合法性（fd 是否有效？buf 是否在用户地址空间？有没有读权限？）</span></span>
<span class="line"><span>  |  &lt; 这一步至关重要，防止用户传一个内核地址让内核帮忙读</span></span>
<span class="line"><span>  |</span></span>
<span class="line"><span>  ⑥ 执行真正的读操作（可能阻塞，此时进程进入阻塞态 &gt; 触发调度）</span></span>
<span class="line"><span>  |</span></span>
<span class="line"><span>  ⑦ 把结果放进返回值寄存器</span></span>
<span class="line"><span>  |</span></span>
<span class="line"><span>  ⑧ 执行 sysret / iret 返回</span></span>
<span class="line"><span>  v</span></span>
<span class="line"><span>用户态</span></span>
<span class="line"><span>  ⑨ 继续执行下一条指令，read 的返回值就是读到的字节数</span></span></code></pre></div><p><strong>必考细节</strong>：</p><ul><li><strong>用户态和内核态用的是两个栈</strong>。切换时栈指针要换（从用户栈换到内核栈），否则用户程序能通过栈溢出影响内核。</li><li><strong>不是所有寄存器都保存</strong>。x86-64 的 <code>syscall</code> 只保存必要的几个（<code>rcx</code>、<code>r11</code>），其余由内核自己决定要不要存。这比&quot;保存全部寄存器&quot;快得多。</li><li><strong>参数不能直接传指针就完事</strong>。内核必须验证这个指针指向用户空间（用 <code>access_ok</code>），否则用户传个内核地址就能读内核数据——这是经典漏洞来源。</li></ul><h3 id="三、中断-异常-陷阱-三种-打断" tabindex="-1">三、中断 / 异常 / 陷阱：三种&quot;打断&quot; <a class="header-anchor" href="#三、中断-异常-陷阱-三种-打断" aria-label="Permalink to &quot;三、中断 / 异常 / 陷阱：三种&quot;打断&quot;&quot;">​</a></h3><table tabindex="0"><thead><tr><th>类型</th><th>来源</th><th>同步/异步</th><th>例子</th></tr></thead><tbody><tr><td><strong>中断</strong></td><td>外部硬件</td><td>异步</td><td>网卡收到包、磁盘读完、定时器到点</td></tr><tr><td><strong>异常</strong></td><td>CPU 执行指令时出错</td><td>同步</td><td>除零、缺页、非法指令、段错误</td></tr><tr><td><strong>陷阱（trap）</strong></td><td>程序主动触发</td><td>同步</td><td>系统调用、断点 <code>int3</code></td></tr></tbody></table><p><strong>共同点</strong>：都会让 CPU 从用户态切到内核态，都走&quot;中断向量表 &gt; 处理程序&quot;这条路。</p><p><strong>差别</strong>：中断随时可能来（异步），异常和陷阱是&quot;执行到某条指令&quot;才发生（同步）。</p><h3 id="四、为什么系统调用-慢" tabindex="-1">四、为什么系统调用&quot;慢&quot; <a class="header-anchor" href="#四、为什么系统调用-慢" aria-label="Permalink to &quot;四、为什么系统调用&quot;慢&quot;&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>一次系统调用的开销：</span></span>
<span class="line"><span>  ① 特权级切换（约几十纳秒）</span></span>
<span class="line"><span>  ② 保存/恢复寄存器现场</span></span>
<span class="line"><span>  ③ 切换栈</span></span>
<span class="line"><span>  ④ 可能污染 TLB 和 CPU 缓存（内核代码和数据挤掉了用户的热数据）</span></span>
<span class="line"><span>  ⑤ 参数校验</span></span></code></pre></div><p>现代 CPU 上大约 <strong>几百纳秒到 1 微秒</strong>。听起来不多，但如果你在一个循环里调 100 万次，就是 1 秒。</p><p><strong>三个优化手段</strong>：</p><ol><li><strong>批量</strong>：<code>readv</code>/<code>writev</code> 一次传多个缓冲区；<code>epoll_wait</code> 一次返回多个事件。</li><li><strong>vDSO</strong>：把 <code>gettimeofday</code>、<code>clock_gettime</code> 这类&quot;只读内核数据&quot;的调用做成用户态可直接读的共享内存，<strong>完全不走系统调用</strong>。</li><li><strong>减少拷贝</strong>：<code>mmap</code>、零拷贝（见 04 篇）。</li></ol><h3 id="五、宏内核-vs-微内核-了解即可-但常被问" tabindex="-1">五、宏内核 vs 微内核（了解即可，但常被问） <a class="header-anchor" href="#五、宏内核-vs-微内核-了解即可-但常被问" aria-label="Permalink to &quot;五、宏内核 vs 微内核（了解即可，但常被问）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>宏内核（Linux）：所有服务（文件系统、驱动、网络协议栈）都在内核态</span></span>
<span class="line"><span>  优点：模块间直接函数调用，快</span></span>
<span class="line"><span>  缺点：一个驱动有 bug，整个系统崩</span></span>
<span class="line"><span></span></span>
<span class="line"><span>微内核（QNX、seL4）：内核只保留最基础的东西（调度、IPC、内存），其他都做成用户态服务</span></span>
<span class="line"><span>  优点：隔离好，驱动崩了不影响内核</span></span>
<span class="line"><span>  缺点：服务之间要靠 IPC 通信，频繁切换，性能差</span></span></code></pre></div><p>Linux 走的是宏内核 + 模块化（驱动可以动态加载），实际工程上更实用。</p><h2 id="为什么这么设计" tabindex="-1">为什么这么设计 <a class="header-anchor" href="#为什么这么设计" aria-label="Permalink to &quot;为什么这么设计&quot;">​</a></h2><h3 id="反事实-1-如果所有程序都在内核态运行" tabindex="-1">反事实 1：如果所有程序都在内核态运行 <a class="header-anchor" href="#反事实-1-如果所有程序都在内核态运行" aria-label="Permalink to &quot;反事实 1：如果所有程序都在内核态运行&quot;">​</a></h3><ul><li>A 程序一个野指针，改掉 B 程序的数据 &gt; 数据错乱，且<strong>无法追查是谁干的</strong>。</li><li>A 程序死循环且关掉中断 &gt; <strong>整个系统永久卡死</strong>，只能重启。</li><li>任何程序都能读你的密码、改你的文件，操作系统毫无意义。</li></ul><h3 id="反事实-2-如果没有系统调用-用户程序直接操作硬件" tabindex="-1">反事实 2：如果没有系统调用（用户程序直接操作硬件） <a class="header-anchor" href="#反事实-2-如果没有系统调用-用户程序直接操作硬件" aria-label="Permalink to &quot;反事实 2：如果没有系统调用（用户程序直接操作硬件）&quot;">​</a></h3><ul><li>每个程序都要自己写网卡驱动、磁盘驱动 &gt; 不可能。</li><li>两个程序同时操作同一块磁盘 &gt; 数据损坏。</li><li>没有统一的资源分配 &gt; 谁先抢到算谁的，无法公平。</li></ul><p>系统调用的本质是**&quot;把危险的、需要协调的操作收归中央&quot;**。中央就是内核，它同时扮演三个角色：<strong>权限检查员、资源调度员、设备代理</strong>。</p><h3 id="反事实-3-如果系统调用不需要切换特权级" tabindex="-1">反事实 3：如果系统调用不需要切换特权级 <a class="header-anchor" href="#反事实-3-如果系统调用不需要切换特权级" aria-label="Permalink to &quot;反事实 3：如果系统调用不需要切换特权级&quot;">​</a></h3><p>那就等于取消隔离。所以&quot;系统调用慢&quot;不是设计缺陷，<strong>是隔离的代价</strong>。所有优化（vDSO、批量、零拷贝）都是在&quot;不放弃隔离&quot;的前提下省开销。</p><h2 id="面试怎么问" tabindex="-1">面试怎么问 <a class="header-anchor" href="#面试怎么问" aria-label="Permalink to &quot;面试怎么问&quot;">​</a></h2><p><strong>Q：用户态和内核态的区别？为什么要分？</strong></p><blockquote><p>区别在<strong>特权级</strong>：用户态不能执行特权指令（改页表、关中断、访问 IO 端口），内核态可以。 为什么要分：<strong>隔离与保护</strong>。不分的话，一个程序的 bug 能搞崩整个系统，任何程序都能读别人的数据。</p></blockquote><p><strong>Q：系统调用的过程？</strong></p><blockquote><p>按上面 ①~⑨ 说，重点突出三件事：<strong>传调用号 &gt; 硬件切特权级 &gt; 查表执行 &gt; 校验参数 &gt; 返回</strong>。 加分点：<strong>用户栈和内核栈是两个栈</strong>；<strong>参数里的指针必须校验</strong>。</p></blockquote><p><strong>Q：中断和异常的区别？</strong></p><blockquote><p>中断是外部硬件异步触发（网卡、定时器），异常是 CPU 执行指令时同步产生（缺页、除零）。系统调用属于陷阱，是程序主动触发的同步事件。</p></blockquote><p><strong>Q：为什么系统调用开销大？能优化吗？</strong></p><blockquote><p>开销来自特权级切换 + 保存现场 + 切栈 + 缓存污染。优化手段：vDSO（把只读调用做成用户态直接读）、批量调用、<code>mmap</code> 减少拷贝、<code>io_uring</code> 把多次调用合并成一次提交。</p></blockquote><p><strong>追问链</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>系统调用怎么进入内核？</span></span>
<span class="line"><span>  &gt; 为什么不能直接 call 内核函数？（特权级不同，硬件不允许）</span></span>
<span class="line"><span>    &gt; 切换时保存了什么？（返回地址、标志位、栈指针 &gt; 切内核栈）</span></span>
<span class="line"><span>      &gt; 内核怎么知道要执行哪个调用？（eax 里的系统调用号 &gt; 查表）</span></span>
<span class="line"><span>        &gt; 用户传个内核地址进来会怎样？（必须校验，否则是提权漏洞）</span></span>
<span class="line"><span>          &gt; 每次调用都这么贵，怎么优化？（vDSO / 批量 / 零拷贝）</span></span></code></pre></div><h2 id="和其他知识的连接" tabindex="-1">和其他知识的连接 <a class="header-anchor" href="#和其他知识的连接" aria-label="Permalink to &quot;和其他知识的连接&quot;">​</a></h2><ul><li><strong>&lt; 来自</strong> <a href="/study-hub/bagu/os/01">进程与线程：谁在跑，跑的时候带着什么</a>：<code>fork</code>/<code>clone</code>/<code>execve</code> 都是系统调用；上下文切换发生在内核态</li><li><strong>&lt; 来自</strong> <a href="/study-hub/bagu/os/02">虚拟内存：让每个程序都以为自己独占一台机器</a>：缺页是异常，处理在特权级切换后进行；页表只能内核改</li><li><strong>&lt; 来自</strong> <a href="/study-hub/bagu/os/04">IO 模型与零拷贝：等设备的时候，CPU 在干什么</a>：所有 IO 系统调用都要过这道门；<code>epoll_create</code>/<code>epoll_wait</code> 都是系统调用</li><li><strong>&gt; 影响</strong> <a href="/study-hub/bagu/network/01">分层模型与一次请求的一生</a>：<code>send</code>/<code>recv</code> 是系统调用，数据在用户缓冲区和内核 socket 缓冲区之间来回</li><li><strong>&gt; 影响</strong> 工程实践：容器（Docker）的隔离靠 namespace + cgroup，但<strong>共享同一个内核</strong>——这就是&quot;容器不如虚拟机隔离强&quot;的根本原因</li></ul><h2 id="自测-3-问" tabindex="-1">自测 3 问 <a class="header-anchor" href="#自测-3-问" aria-label="Permalink to &quot;自测 3 问&quot;">​</a></h2><p><strong>Q1：为什么系统调用时用户态和内核态必须用两个不同的栈？</strong></p><details class="details custom-block"><summary>点开看答案</summary><p>因为<strong>用户栈不可信</strong>。</p><p>如果内核继续用用户栈，用户程序可以：</p><ul><li>故意把栈指针指到一个精心构造的位置，让内核的局部变量覆盖到内核数据；</li><li>或者栈空间不够时，内核写入会踩到用户的其他内存。</li></ul><p>用独立的内核栈，等于给内核一块<strong>用户碰不到的工作区</strong>。这也是为什么内核栈通常很小（8~16KB）且不能递归太深——栈溢出会直接崩内核。</p></details><p><strong>Q2：<code>gettimeofday</code> 为什么可以不走系统调用？</strong></p><details class="details custom-block"><summary>点开看答案</summary><p>因为内核把&quot;当前时间&quot;这块数据放在一页<strong>只读的共享内存</strong>里，映射到每个进程的地址空间（vDSO）。</p><p>用户程序调用 <code>gettimeofday</code> 时，库函数直接读这块内存 + 用 CPU 的 <code>rdtsc</code> 指令补偿，<strong>完全在用户态完成</strong>，一次特权级切换都没有。</p><p>前提是：这个操作<strong>只读、不需要内核做任何决策</strong>。一旦需要内核参与（比如改时间、需要加锁），就必须走真正的系统调用。</p></details><p><strong>Q3：容器为什么&quot;隔离性不如虚拟机&quot;？</strong></p><details class="details custom-block"><summary>点开看答案</summary><p>因为容器<strong>共享宿主机的内核</strong>，只是用 namespace 让进程&quot;看不见&quot;别的进程和网络，用 cgroup 限制资源用量。</p><p>推论：</p><ol><li>内核漏洞（提权漏洞）一旦被利用，容器里能直接影响宿主机内核 &gt; 逃逸。</li><li>容器里的进程看到的 <code>/proc</code>、内核版本、系统调用表都是同一个。</li><li>无法运行不同内核版本（比如在 Linux 上跑 Windows 容器）。</li></ol><p>虚拟机有独立的 Guest OS 内核，跑在 hypervisor 之上，隔离边界是硬件虚拟化，强得多——代价是启动慢、资源开销大。</p></details><h2 id="类比失效处-易错点" tabindex="-1">类比失效处 / 易错点 <a class="header-anchor" href="#类比失效处-易错点" aria-label="Permalink to &quot;类比失效处 / 易错点&quot;">​</a></h2><ul><li><strong>&quot;前厅后厨&quot;会让人以为切换是&quot;走过去&quot;</strong>。实际是 CPU 硬件在一条指令内完成特权级切换，没有&quot;走过去&quot;的时间，但有保存现场和缓存污染的开销。</li><li><strong>&quot;系统调用就是函数调用&quot;是错的</strong>。普通函数调用只压栈跳转，系统调用要换特权级、换栈、查表、校验。</li><li><strong><code>printf</code> 不是系统调用</strong>。它是 C 库函数，内部可能调 <code>write</code>。<code>malloc</code> 也不是，它内部用 <code>brk</code>/<code>mmap</code>。区分&quot;库函数&quot;和&quot;系统调用&quot;是常见考点。</li><li><strong>中断不等于异常，也不等于信号</strong>。信号是内核发给进程的软件通知（<code>SIGSEGV</code>），是异常处理之后可能产生的结果，不是同一层的东西。</li><li><strong>&quot;内核态可以做任何事&quot;要加限定</strong>。内核态也不能违反硬件约束（比如访问不存在的物理地址仍会崩），只是它有权限配置这些约束。</li></ul><h2 id="✅-验收清单" tabindex="-1">✅ 验收清单 <a class="header-anchor" href="#✅-验收清单" aria-label="Permalink to &quot;✅ 验收清单&quot;">​</a></h2><ul><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="0"> 能说出用户态和内核态各不能做什么，并举 3 个&quot;特权指令&quot;的例子</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="1"> 能按顺序说出系统调用的 6 个关键步骤（传号 &gt; 陷入 &gt; 保存现场 &gt; 查表 &gt; 校验 &gt; 返回）</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="2"> 能解释&quot;为什么用户栈和内核栈必须分开&quot;</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="3"> 能区分中断、异常、陷阱，各举一个例子</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="4"> 能说出系统调用慢在哪，以及至少两种优化手段</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="5"> 能用&quot;共享内核&quot;解释容器隔离性弱于虚拟机的原因</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="6"> 合上书，用自己的话讲 3 分钟，中途不卡壳</li></ul>`,60)])])}const h=a(e,[["render",l]]);export{u as __pageData,h as default};
